CREATE TABLE IF NOT EXISTS task_criterion_state(criterion_id TEXT PRIMARY KEY NOT NULL REFERENCES criteria(id),state TEXT NOT NULL DEFAULT 'unverified',reason TEXT NOT NULL DEFAULT '',latest_evidence_id TEXT REFERENCES evidence(id),instruction_revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS task_impact_index(criterion_id TEXT NOT NULL REFERENCES criteria(id),pattern TEXT NOT NULL,PRIMARY KEY(criterion_id,pattern));
CREATE TABLE IF NOT EXISTS task_check_attempts(operation_key TEXT PRIMARY KEY NOT NULL,task_id TEXT NOT NULL REFERENCES tasks(id),check_id TEXT NOT NULL REFERENCES checks(id),run_id TEXT NOT NULL REFERENCES runs(id),prepared TEXT NOT NULL CHECK(json_valid(prepared)),snapshot TEXT NOT NULL CHECK(json_valid(snapshot)),producer_snapshot TEXT NOT NULL CHECK(json_valid(producer_snapshot)),evidence_id TEXT REFERENCES evidence(id),state TEXT NOT NULL DEFAULT 'intent');
CREATE TABLE IF NOT EXISTS task_verifier_jobs(id TEXT PRIMARY KEY NOT NULL,task_id TEXT NOT NULL REFERENCES tasks(id),root_run_id TEXT NOT NULL REFERENCES runs(id),round INTEGER NOT NULL CHECK(round BETWEEN 1 AND 2),instruction_revision INTEGER NOT NULL,input TEXT NOT NULL CHECK(json_valid(input)),verifier_run_id TEXT REFERENCES runs(id),state TEXT NOT NULL DEFAULT 'pending',error TEXT,verdict TEXT CHECK(verdict IS NULL OR json_valid(verdict)));
CREATE TABLE IF NOT EXISTS task_verifier_rounds(root_run_id TEXT NOT NULL REFERENCES runs(id),criterion_id TEXT NOT NULL REFERENCES criteria(id),rounds INTEGER NOT NULL DEFAULT 0 CHECK(rounds BETWEEN 0 AND 2),verification_scope TEXT NOT NULL DEFAULT 'task',PRIMARY KEY(root_run_id,criterion_id,verification_scope));
CREATE TABLE IF NOT EXISTS task_criterion_exemptions(criterion_id TEXT PRIMARY KEY NOT NULL REFERENCES criteria(id),criterion_version INTEGER NOT NULL,instruction_revision INTEGER NOT NULL,justification TEXT NOT NULL,actor TEXT NOT NULL,recorded_at INTEGER NOT NULL DEFAULT(unixepoch()));
